const BY_ID = new Map(SCREENS.map((s) => [s.id, s]));
const BY_ROUTE = new Map(SCREENS.map((s) => [s.route, s]));

export function screen(id: string): Screen {
  const s = BY_ID.get(id);
  if (!s) throw new Error(`Unknown screen ${id}`);
  return s;
}

export function screenAt(route: string): Screen | undefined {
  return BY_ROUTE.get(route);
}

export function routeOf(n: number): string {
  return screen(`SCR-${String(n).padStart(3, "0")}`).route;
}
